//! komga tool surface.
//!
//! Endpoint registry: `komga.{list, detail, create, update, delete}` —
//! generated by `#[endpoint_resource]`.
//!
//! Library upkeep:
//!   - `komga.library.audit`   mis-numbered books, duplicates, misfiled/unparseable files, gaps
//!   - `komga.books.renumber`  write filename issue numbers back, locked (dry run by default)
//!   - `komga.library.scan`    trigger a library scan (dry run by default)
//!
//! Libraries default to the one named `comics`: the filename rules are comic
//! conventions and would misread manga chapters.

use plugin_toolkit::prelude::*;

use crate::api::{Komga, Library};
use crate::audit::{self, AuditReport, LibraryData, Renumber, Skipped};
use crate::execute;

#[endpoint_resource(plugin = "komga")]
pub struct KomgaEndpoint {
    pub name: String,
    /// Komga API key, sent as `X-API-Key`.
    #[secret]
    pub api_key: String,
    /// Skip TLS verification (self-signed certs).
    pub insecure: bool,
    pub enabled: bool,
}

pub async fn connect(name: &str) -> Result<Komga> {
    let row = endpoint_db::require(name)?;
    let api_key = plugin_toolkit::secrets::resolve_scoped(
        "komga",
        name,
        "api_key",
        (!row.api_key.is_empty()).then_some(row.api_key.as_str()),
    )?;
    let base_url = route::resolve_reachable(name, &row.routes, row.insecure).await?;
    Komga::new(&base_url, &api_key, row.insecure)
}

/// Auto-selected only when named exactly `comics`/`comic`, so a mixed
/// library (`Comics & Manga`) is never picked up silently.
fn is_comics(l: &Library) -> bool {
    matches!(l.name.trim().to_lowercase().as_str(), "comics" | "comic")
}

/// Libraries in scope: one library, or the comics libraries.
async fn libraries_in_scope(k: &Komga, library_id: Option<&str>) -> Result<Vec<Library>> {
    if let Some(lid) = library_id {
        return Ok(vec![k.library(lid).await?]);
    }
    let libs: Vec<Library> = k.libraries().await?.into_iter().filter(is_comics).collect();
    if libs.is_empty() {
        bail!("no library is named \"comics\"; pass a library id");
    }
    Ok(libs)
}

async fn collect(
    k: &Komga,
    library_id: Option<&str>,
    series_id: Option<&str>,
) -> Result<Vec<LibraryData>> {
    match (library_id, series_id) {
        (Some(_), Some(_)) => bail!("pass a library id or a series id, not both"),
        (_, Some(sid)) => {
            let series = k.series(sid).await?;
            Ok(vec![LibraryData {
                library: k.library(&series.library_id).await?,
                books: k.series_books(sid).await?,
                series: vec![series],
            }])
        }
        (lid, None) => {
            let mut out = Vec::new();
            for library in libraries_in_scope(k, lid).await? {
                out.push(LibraryData {
                    series: k.library_series(&library.id).await?,
                    books: k.library_books(&library.id).await?,
                    library,
                });
            }
            Ok(out)
        }
    }
}

/// Mutating verbs act on an explicit scope; `all` means the comics libraries.
fn require_scope(
    tool: &str,
    library_id: &Option<String>,
    series_id: &Option<String>,
    all: bool,
) -> Result<()> {
    if library_id.is_none() && series_id.is_none() && !all {
        bail!("{tool}: pick a scope: library_id, series_id, or all");
    }
    Ok(())
}

#[orca_struct]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Failure {
    pub id: String,
    pub error: String,
}

// ═══════════════════════════════════════════════════════════════════════════
// komga.library.audit
// ═══════════════════════════════════════════════════════════════════════════

#[orca_struct(args)]
pub struct AuditArgs {
    /// Registered komga endpoint name.
    #[arg(long)]
    pub name: String,
    /// Komga library id. Omitted, the library named `comics`.
    #[arg(long)]
    pub library_id: Option<String>,
    /// Komga series id, to audit one series.
    #[arg(long)]
    pub series_id: Option<String>,
}

/// Read-only audit of comic numbering. Komga numbers books by sort order, not
/// by the number in the filename, so series with gaps read out of order. Per
/// series: books whose Komga number differs from the filename's, books sharing
/// a number, files that look like another series, files with no number,
/// edge cases (decimal/suffixed issues, volumes, collected editions in an
/// issue series), and missing issue ranges.
#[orca_tool(domain = "komga", verb = "library.audit", role = "read")]
async fn komga_library_audit(args: AuditArgs, _ctx: &ToolCtx) -> Result<AuditReport> {
    let k = connect(&args.name).await?;
    let data = collect(&k, args.library_id.as_deref(), args.series_id.as_deref()).await?;
    Ok(audit::audit(&args.name, &data))
}

// ═══════════════════════════════════════════════════════════════════════════
// komga.books.renumber
// ═══════════════════════════════════════════════════════════════════════════

#[orca_struct(args)]
pub struct RenumberArgs {
    /// Registered komga endpoint name.
    #[arg(long)]
    pub name: String,
    /// Komga library id.
    #[arg(long)]
    pub library_id: Option<String>,
    /// Komga series id.
    #[arg(long)]
    pub series_id: Option<String>,
    /// The library named `comics`.
    #[arg(long)]
    #[serde(default)]
    pub all: bool,
    /// Overwrite numbers that are already locked.
    #[arg(long)]
    #[serde(default)]
    pub force: bool,
    /// Apply. Omitted, returns the plan and changes nothing.
    #[arg(long)]
    #[serde(default)]
    pub execute: bool,
}

#[orca_struct]
#[derive(Debug, Clone, PartialEq)]
pub struct RenumberReport {
    pub name: String,
    pub execute: bool,
    /// Books whose number and sort number would be set (and locked).
    pub planned: Vec<Renumber>,
    /// Mis-numbered or unparseable books left alone, with the reason.
    pub skipped: Vec<Skipped>,
    /// Book ids updated (execute only).
    pub applied: Vec<String>,
    pub failed: Vec<Failure>,
}

/// **Fix issue numbering**: set each mis-numbered book's `number` and
/// `numberSort` to the filename's issue number, with both locks so rescans
/// keep them. Skips books already right, locked numbers (unless `force`),
/// decimal and suffixed issues, volumes, unparseable files, and files that
/// look like another series. Without `execute`, returns the plan.
///
/// `execute` applies the whole plan as computed when it runs, with no confirm
/// list: every write is a locked metadata change, reversible by another write.
#[orca_tool(
    domain = "komga",
    verb = "books.renumber",
    role = "admin",
    execute_gated = false
)]
async fn komga_books_renumber(args: RenumberArgs, ctx: &ToolCtx) -> Result<RenumberReport> {
    const TOOL: &str = "komga.books.renumber";
    execute::require_admin(TOOL, ctx)?;
    require_scope(TOOL, &args.library_id, &args.series_id, args.all)?;
    let k = connect(&args.name).await?;
    let data = collect(&k, args.library_id.as_deref(), args.series_id.as_deref()).await?;
    let (planned, skipped) = audit::renumber_plan(&data, args.force);
    let mut applied = Vec::new();
    let mut failed = Vec::new();
    if args.execute {
        for p in &planned {
            match k.set_number(&p.book_id, &p.number, p.number_sort).await {
                Ok(()) => applied.push(p.book_id.clone()),
                Err(e) => failed.push(Failure {
                    id: p.book_id.clone(),
                    error: format!("{e:#}"),
                }),
            }
        }
    }
    Ok(RenumberReport {
        name: args.name,
        execute: args.execute,
        planned,
        skipped,
        applied,
        failed,
    })
}

// ═══════════════════════════════════════════════════════════════════════════
// komga.library.scan
// ═══════════════════════════════════════════════════════════════════════════

#[orca_struct(args)]
pub struct ScanArgs {
    /// Registered komga endpoint name.
    #[arg(long)]
    pub name: String,
    /// Komga library id. Omitted, the library named `comics`.
    #[arg(long)]
    pub library_id: Option<String>,
    /// Re-read every file, not just changed ones.
    #[arg(long)]
    #[serde(default)]
    pub deep: bool,
    /// Apply. Omitted, names the libraries and scans nothing.
    #[arg(long)]
    #[serde(default)]
    pub execute: bool,
}

#[orca_struct]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ScanTarget {
    pub library_id: String,
    pub library_name: String,
    pub deep: bool,
    pub triggered: bool,
}

#[orca_struct]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ScanReport {
    pub name: String,
    pub execute: bool,
    pub libraries: Vec<ScanTarget>,
    pub failed: Vec<Failure>,
}

/// **Scan a library** (`deep` re-reads every file). Komga queues the scan and
/// returns at once. Without `execute`, names the libraries and scans nothing.
#[orca_tool(
    domain = "komga",
    verb = "library.scan",
    role = "admin",
    execute_gated = false
)]
async fn komga_library_scan(args: ScanArgs, ctx: &ToolCtx) -> Result<ScanReport> {
    const TOOL: &str = "komga.library.scan";
    execute::require_admin(TOOL, ctx)?;
    let k = connect(&args.name).await?;
    let mut libraries = Vec::new();
    let mut failed = Vec::new();
    for lib in libraries_in_scope(&k, args.library_id.as_deref()).await? {
        let mut t = ScanTarget {
            library_id: lib.id.clone(),
            library_name: lib.name.clone(),
            deep: args.deep,
            triggered: false,
        };
        if args.execute {
            match k.scan(&lib.id, args.deep).await {
                Ok(()) => t.triggered = true,
                Err(e) => failed.push(Failure {
                    id: lib.id.clone(),
                    error: format!("{e:#}"),
                }),
            }
        }
        libraries.push(t);
    }
    Ok(ScanReport {
        name: args.name,
        execute: args.execute,
        libraries,
        failed,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn mutations_need_an_explicit_scope() {
        assert!(require_scope("t", &None, &None, false).is_err());
        assert!(require_scope("t", &None, &None, true).is_ok());
        assert!(require_scope("t", &Some("L".into()), &None, false).is_ok());
        assert!(require_scope("t", &None, &Some("S".into()), false).is_ok());
    }

    fn library(id: &str, empty_trash: bool) -> Library {
        Library {
            id: id.into(),
            name: id.into(),
            empty_trash_after_scan: empty_trash,
        }
    }

    #[test]
    fn only_a_library_named_comics_is_auto_selected() {
        assert!(is_comics(&library("Comics", true)));
        assert!(is_comics(&library(" comic ", true)));
        assert!(!is_comics(&library("Comics & Manga", true)));
        assert!(!is_comics(&library("manga", true)));
    }

    #[test]
    fn library_tools_are_not_host_execute_gated() {
        const OWN: [&str; 3] = [
            "komga.library.audit",
            "komga.books.renumber",
            "komga.library.scan",
        ];
        let gated: Vec<&str> = plugin_toolkit::dispatch::execute_gated_names()
            .into_iter()
            .filter(|n| OWN.contains(n))
            .collect();
        assert!(gated.is_empty(), "{gated:?}");
        let role = |n| plugin_toolkit::dispatch::required_role(n);
        assert_eq!(role("komga.library.audit"), Some("read"));
        for n in ["komga.books.renumber", "komga.library.scan"] {
            assert_eq!(role(n), Some("admin"), "{n}");
        }
    }
}
